INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9fcdc925-9593-4bd3-8ff8-83ee88653b95', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "11141450-ec68-4e4d-a228-bd582997d802", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "a0dcea0d-f522-4dcf-a525-04dacd8fc0e1", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "e8688b8c-d96f-4be0-b0ce-7a78b56a3a3c", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "3f1254fa-7d3b-4d9c-9f92-d5e3a4173606", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "c8cfd808-fd0f-4bdd-be13-347a1e594e30", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "e16bfc39-1be0-44ce-a82d-3535eb357b00", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "281d3fbe-fa59-46be-bd52-1e8ee5848261", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "74fd9316-9847-4184-9a5c-047049648a05", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "44afa04c-a9f8-49cf-a238-da5c25a3e843", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "7c3191f6-ca91-4b09-997f-2175e7c9524c", "text": "Igaz", "isCorrect": true}, {"id": "f65bd169-3f41-4ab2-892f-160de0584ba8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bb93f1b0-e1c6-499f-9c95-b6973ba81a24", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "c9cd4274-f13d-4990-933e-3f5cefac65a5", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('53b88f54-3ab3-499c-a132-c595db908c2b', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "7df6796c-b2b3-4903-abee-701317edbf0d", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "badb0871-91c2-4cfa-84bd-3029f6614020", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "d912d7c8-fa99-418d-898b-7b299fa05475", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "d13750e8-9a67-4122-acb7-eedc7a33cf32", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "956eec52-ca12-49c4-bf80-f118c5ee0ed1", "text": "Igaz", "isCorrect": true}, {"id": "9e287440-2c4a-42ef-a2e4-9b4fa4257399", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56e64dba-bdbe-478e-b358-e3cc002c4422", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "4ba760a6-ad93-4c74-a94a-45776a15539d", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "4bf2a124-de9e-4c39-8744-4a0b419df383", "text": "Igaz", "isCorrect": true}, {"id": "3e9bdca5-e221-4f55-b6e3-1abd5239de5f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5a8c8015-aed8-4ccd-80a3-a5a6b063b159", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('eea0b81b-47e9-4e1b-84f1-0d54bae4b6f9', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "c06787ab-2822-4407-84c3-7d4ef4b48e3a", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "8b949695-0a82-4272-b4dc-f75dc23d51cc", "text": "3/5", "isCorrect": true}, {"id": "4536fec2-7b66-4ddc-8a88-17f4e8fe39b6", "text": "12/20", "isCorrect": false}, {"id": "70ada62a-dbb8-4f4d-8436-25633e2a1ce5", "text": "7/9", "isCorrect": false}, {"id": "58c083d2-037e-4ae6-885b-ad00bc69671d", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "49116c4a-424c-427a-bceb-1cc2159eff0e", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "ad82430e-5a29-4ce5-b36d-c99b460c95d9", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "bc1b8f3f-e1a0-4b16-8bb9-b3f77247c8a7", "text": "1/6", "isCorrect": false}, {"id": "9c4eadd1-a5c6-4952-a9b8-64031715eb1f", "text": "2/3", "isCorrect": false}, {"id": "b59ed857-e9d5-48a4-a881-04262a6c4a4e", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "43c04cec-499e-4962-a611-29eed27a24e2", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "3129eebb-0858-4f80-b810-c0ad2f6d02e8", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "b1969218-a554-4d21-97a9-9b7dafc96494", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "c8022540-b371-4b98-adaf-46c11f6e3c17", "text": "Igaz", "isCorrect": true}, {"id": "0d0df9f4-d236-4ae9-9a53-80dc5687bbb8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21c70c5e-48ee-4e5b-9b59-c47cf4fa6ea0", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "a4f17447-bb79-4372-94ce-cd9e96be178e", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0ce526c7-e199-401b-80ee-c46183d231da', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "579432dc-8b4f-4134-9063-d1cbe3cee0e1", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "76eca0c3-5250-4104-9059-49a22cd4f0fe", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "7386f212-d6ce-488c-89e4-61a1f236e27b", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "7ae18e7a-9dd5-4256-ac83-e5a06749baba", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "b432d1bd-c65c-4c23-88f6-f96d82e23564", "text": "1/5", "isCorrect": false}, {"id": "91a6d358-6cbd-445f-8d23-e880b8c8660f", "text": "1/2", "isCorrect": false}, {"id": "9c2f86e0-4c1f-4572-8ef0-de03c5ab95c9", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "9b3701b7-ff24-4adc-982e-17bda1836179", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "30d8f362-0c2e-4ae9-95c4-e76c2edda92d", "text": "Igaz", "isCorrect": true}, {"id": "82a78f6e-4f27-43f6-89cf-b39153cf41ce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1cc2b71a-1df6-41f6-906b-8a5ef6e3557a", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "906bbe36-0f4c-47fe-9c98-a4911eda378e", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "4ba1dccf-4ab7-48a6-94f9-4ccb9e2c3778", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "07836bfd-a51e-476d-a62f-c1c58cb14fc9", "text": "Igaz", "isCorrect": true}, {"id": "d5ef8890-1e0b-4627-a514-84e5877eb316", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1dab18b0-f1e9-43e4-b23a-6673e6cf781e', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "64673e71-a11c-4d97-8d92-6c8e604eda93", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "4e95ee48-0c7f-46c9-8a70-65b8a5539b7e", "text": "1/3", "isCorrect": true}, {"id": "133a6a0a-66e7-42dc-9ebc-0e30099dc3c8", "text": "1/4", "isCorrect": false}, {"id": "3899c331-e141-42d9-ad93-21dce89ee090", "text": "2/3", "isCorrect": false}, {"id": "fde811d0-35b8-4336-9020-00b4fea69b76", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "89018bae-a559-4268-ba68-52fa41294b39", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "65021fe8-f8ec-4c54-b860-d62acb023e52", "text": "1/4", "isCorrect": true}, {"id": "759117f0-7c2e-456f-a100-979604556c2a", "text": "1/5", "isCorrect": false}, {"id": "65b4e0e6-5891-4600-afbc-95612af6c8e5", "text": "2/5", "isCorrect": false}, {"id": "30412873-8631-4703-8d53-99b5cddbafa6", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "3061b89a-e4a1-40c3-be6a-006cc8b46895", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "88a15158-267e-4a93-8b45-a89099862b27", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "e68965a0-43f8-4fc1-85ec-27e8ab784677", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "a6193bc9-d330-4b88-8147-dd6f5f827366", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "061646be-ee1a-45d3-b3fc-3b73554625d9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91f79b56-07bd-4eee-92fe-c5bf33d96dd5", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "9705ca55-ab7d-4c34-921e-e485e205fc5b", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "e4f93f3d-2476-408f-b411-f1c10af67c5d", "text": "Igaz", "isCorrect": true}, {"id": "47b44c75-e094-4145-a969-d201be9490e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bb5e1449-fbcb-4e4d-88c3-ba81b0125362', '21feff02-016d-46e2-bb9d-c27495133b1b', '46. óra: Témazáró dolgozat', 'Témazáró számonkérés a Törtek fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b62f1773-196e-4621-ae3c-d9fc00b160ac", "text": "1. Mennyi 2/3 + 1/6? (4/6 + 1/6)", "type": "multiple-choice", "options": [{"id": "c1afbae0-45b6-45a2-9a48-d7896ea427c9", "text": "5/6", "isCorrect": true}, {"id": "c52990f3-007e-41b0-9085-82481c4cfdab", "text": "3/9", "isCorrect": false}, {"id": "fbec7140-29f0-4d2f-b495-7843c6c6f3be", "text": "3/6", "isCorrect": false}, {"id": "c6759c4a-45a1-430a-9c99-330b39318194", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "f97724ad-6e8b-434a-a31d-f108258ff8a8", "text": "2. Mennyi 3/5 * 5/6?", "type": "multiple-choice", "options": [{"id": "599de69e-a5fb-42e4-a2bd-526242dd70c9", "text": "15/30 (azaz 1/2)", "isCorrect": true}, {"id": "ad72ce7c-d3c0-471e-88c5-1231a56f9f72", "text": "8/11", "isCorrect": false}, {"id": "94770342-329f-4fba-b943-7f193ae9387a", "text": "15/11", "isCorrect": false}, {"id": "4f3b1c3d-bebf-49e7-981f-144362c41f57", "text": "3/6", "isCorrect": false}], "timeLimit": 15}, {"id": "42405091-8ebe-4589-bd9d-a6d890b5c644", "text": "3. Mennyi 3/4 : 1/2? (3/4 * 2/1)", "type": "multiple-choice", "options": [{"id": "6f4e09c9-0727-4dd6-86f2-ec87f2401211", "text": "6/4 (azaz 3/2 vagy 1,5)", "isCorrect": true}, {"id": "1fd04b40-c113-4304-a2ee-43ee187acc84", "text": "3/8", "isCorrect": false}, {"id": "db2ed09a-6279-435a-8de8-3cc9df22f1c6", "text": "1/4", "isCorrect": false}, {"id": "14ec4551-def8-4ae4-ba60-6b0e45491b64", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "b6e1fd13-fb75-46e6-b36a-701b34541016", "text": "4. Mi a 4/9 reciproka?", "type": "multiple-choice", "options": [{"id": "752e5460-b384-4282-953e-09bb6f15e803", "text": "9/4", "isCorrect": true}, {"id": "720bae10-7e2a-4bbb-a5ef-ea368dc96e4b", "text": "-4/9", "isCorrect": false}, {"id": "8e0d8b04-1038-45ec-bca3-4dbe3fc096ec", "text": "1/4", "isCorrect": false}, {"id": "121878b9-457a-4c93-a403-b5521fb02706", "text": "4/9", "isCorrect": false}], "timeLimit": 15}, {"id": "d4f9f123-a5f3-4dc8-9a34-f6b4c5688a10", "text": "5. Mennyi 2,4 + 3,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6.2"}, {"id": "8ad69466-8cc2-4f92-8ef9-3d2d01f80691", "text": "6. Mennyi 1,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "f241ee48-3c94-458f-860a-80970877cddf", "text": "7. Mennyi 4,2 : 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "6457f626-b913-437a-b4df-a8f57714f7c7", "text": "8. Mennyi 60-nak a 2/3 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "3a4820ae-cfda-47da-aafd-7d72fba6ddd9", "text": "9. A 0,25 megegyezik az 1/4 törttel.", "type": "true-false", "options": [{"id": "d1ab43b0-ad29-4d00-8049-cc3d6b89c528", "text": "Igaz", "isCorrect": true}, {"id": "6b2b31b5-ec0b-4660-ab12-21839a334d4f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d9018b0d-213e-42af-8bdb-4d5d84f941e9", "text": "10. Mennyi (1,5 + 0,5) * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('40226f12-7e0b-4b53-9db8-342709be5a59', '21feff02-016d-46e2-bb9d-c27495133b1b', '47. óra: Témazáró dolgozat értékelése', 'A dolgozat megbeszélése, a törtek műveleteinek összefoglaló értékelése.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "d01b5f76-4311-459a-97f7-3f74601c839e", "text": "Mi a leggyakoribb hiba a törtek osztásakor?", "type": "multiple-choice", "options": [{"id": "19b20546-5cee-4674-a2ef-b398c2bef183", "text": "Az osztó reciprokával való szorzás elfelejtése", "isCorrect": true}, {"id": "a1f91035-c306-471b-bebd-afd8594bb4c1", "text": "A számlálók leírása", "isCorrect": false}, {"id": "40c1b142-cbf2-45df-8414-dadeff17a1f6", "text": "A zárójel használata", "isCorrect": false}, {"id": "29ae8f32-1046-4909-ab3a-cb851a461bc1", "text": "A művelet elvégzése", "isCorrect": false}], "timeLimit": 15}, {"id": "165d03df-8efa-4578-8468-4bdce50ceced", "text": "Tizedes törtek osztásakor az osztónak egész számnak kell lennie a művelet elvégzése előtt.", "type": "true-false", "options": [{"id": "363fe2d3-e7c2-415d-b30c-54c6ed4ac837", "text": "Igaz", "isCorrect": true}, {"id": "1fb3ab57-a801-40c8-a85b-1939bd61bd7a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "91baabe1-8408-4de7-9ceb-304aac16bb03", "text": "Mennyi 1/2 * 4/5?", "type": "multiple-choice", "options": [{"id": "e2673ff0-0e06-4584-aa9f-3bfa362beaaa", "text": "2/5", "isCorrect": true}, {"id": "c095e1db-e639-413d-9b49-acfb22fa40b6", "text": "4/10", "isCorrect": false}, {"id": "0dbd752c-066d-40cd-a1b9-3a9a657a3861", "text": "1/5", "isCorrect": false}, {"id": "d7da1417-a549-48fb-8fa2-36f960538c03", "text": "5/7", "isCorrect": false}], "timeLimit": 15}, {"id": "0bc16df3-478f-4806-99e9-86222a194f63", "text": "Mennyi 2,5 : 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "5fccc02d-07f7-4a69-b20a-e4aafee2b2b7", "text": "A gyakorlás és a hibák javítása segít a jobb teljesítmény elérésében.", "type": "true-false", "options": [{"id": "b34afc80-1db0-4025-8829-47c8b1102548", "text": "Igaz", "isCorrect": true}, {"id": "f1b9ae4b-a348-4eab-96b5-1028174b3ee2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c6ee843-e4f4-460b-9f45-5b6e125531fa", "text": "Mennyi 100-nak a 3/10 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "f9b6738d-d016-4d2d-a4e5-cbe88c50fd0f", "text": "Mennyi 0,8 + 0,4 - 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cc42830b-256c-42bf-81cc-203d3284c6b9', '21feff02-016d-46e2-bb9d-c27495133b1b', '48. óra: Síkbeli alakzatok', 'Szögek fajtái, háromszögek csoportosítása, belső szögek összege (180°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "b3f48259-dde9-40cc-a990-cb83a328ec5d", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "5e03ed0f-2ca0-4363-a1b4-14fd881ea663", "text": "Milyen szög a 90°-nál kisebb pozitív szög?", "type": "multiple-choice", "options": [{"id": "462068bc-e9c6-41fb-bb8b-a8c80203677b", "text": "Hegyesszög", "isCorrect": true}, {"id": "b84f0831-ca5c-4588-bb37-8e1891bf6949", "text": "Derékszög", "isCorrect": false}, {"id": "22a1b3b5-1e91-41c8-82b9-51b10936a8c4", "text": "Tompaszög", "isCorrect": false}, {"id": "b99334c6-5c22-434c-8aff-04d7c2779fd5", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "bbf10a7e-4c29-4323-bc63-935ae09774f2", "text": "Milyen szög a pontosan 90°-os szög?", "type": "multiple-choice", "options": [{"id": "35223a5b-0bd3-48a4-959d-2ed9599e1bd5", "text": "Derékszög", "isCorrect": true}, {"id": "79d93a3f-4d04-4eff-ae31-1d3b782b7e1a", "text": "Hegyesszög", "isCorrect": false}, {"id": "d98f08a5-4391-4ec6-88c3-0dbed2e51f1a", "text": "Tompaszög", "isCorrect": false}, {"id": "bbb94ae0-75dc-4b07-8d2f-6d95eab5f2cb", "text": "Teljes szög", "isCorrect": false}], "timeLimit": 15}, {"id": "a6ea0bef-f0b7-408f-85c2-277637e1b923", "text": "Milyen szög a 90° és 180° közötti szög?", "type": "multiple-choice", "options": [{"id": "51fa6ed7-46db-4891-b1dc-354985eb069c", "text": "Tompaszög", "isCorrect": true}, {"id": "19e171d6-a9f1-4ebe-87a2-55ceacf1082d", "text": "Hegyesszög", "isCorrect": false}, {"id": "2f2bbe78-60ef-45f4-802a-feaaf959324b", "text": "Derékszög", "isCorrect": false}, {"id": "d6f07077-1631-42f5-93e5-4f85b0009c70", "text": "Egyenesszög", "isCorrect": false}], "timeLimit": 15}, {"id": "8f41490f-b249-443b-9b9b-d2bda770ec9a", "text": "Ha a háromszög két szöge 50° és 60°, mennyi a harmadik szög?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "5d1969d0-60af-4d16-b974-3c39bc66b7ae", "text": "A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "0156a871-660d-4bd1-b2cf-b766b1e1d720", "text": "Igaz", "isCorrect": true}, {"id": "ae996d02-5dde-4c94-b38c-8a4f989c124e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "13acb50b-be65-4738-9dfd-9f00fdabf5ab", "text": "A szabályos háromszög (egyenlő oldalú) minden belső szöge 60°-os.", "type": "true-false", "options": [{"id": "5e86cc11-803d-4c4d-8397-898b9d2394b1", "text": "Igaz", "isCorrect": true}, {"id": "99265f02-cfa5-44b0-8058-72e61daaca29", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('72ca20da-258d-472f-b764-b5ec7c9e5777', '21feff02-016d-46e2-bb9d-c27495133b1b', '49. óra: Síkbeli alakzatok II.', 'Négyszögek fajtái (téglalap, négyzet, rombusz, paralelogramma, trapéz) és szögösszegük (360°).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "9978aaf8-bbdb-48c1-9abe-a54c7bf4bd44", "text": "Mennyi a konvex négyszögek belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "1a499b54-f8fb-4444-a89d-9c4c63a6be3c", "text": "Melyik négyszögnek van minden oldala egyenlő hosszú és minden szöge derékszög?", "type": "multiple-choice", "options": [{"id": "b78cdb6c-c4d1-43dd-80c7-a29f27a76869", "text": "Négyzet", "isCorrect": true}, {"id": "8e887601-d23b-4f8e-9aee-6c765796faf6", "text": "Rombusz", "isCorrect": false}, {"id": "d2136373-2a7b-4e6d-8c45-5ee1daf15845", "text": "Téglalap", "isCorrect": false}, {"id": "c2911bb0-29d6-4d37-9781-617b6d352347", "text": "Trapéz", "isCorrect": false}], "timeLimit": 15}, {"id": "37588000-d201-4422-a864-9457053350e1", "text": "Melyik négyszögnek van minden oldala egyenlő, de nem feltétlenül derékszögűek a szögei?", "type": "multiple-choice", "options": [{"id": "a4eef44d-3694-42c0-b0a5-ecff64adad79", "text": "Rombusz", "isCorrect": true}, {"id": "7de8a149-0749-49ce-958e-fe2863a1da3d", "text": "Téglalap", "isCorrect": false}, {"id": "a22dd235-3d19-44e1-816b-2a7fa30bf30a", "text": "Trapéz", "isCorrect": false}, {"id": "39e46dab-c615-4a22-bfcc-9f57c4eeaaf3", "text": "Deltoid", "isCorrect": false}], "timeLimit": 15}, {"id": "dcbfe944-757e-4d09-9462-d9bc451a4fd9", "text": "A trapéznak van legalább egy pár párhuzamos oldala.", "type": "true-false", "options": [{"id": "b0ab2096-0e2d-4e8a-9831-4ae268f22f71", "text": "Igaz", "isCorrect": true}, {"id": "8520c194-6761-4fa1-8118-9ba3ba6d9315", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56a2f6b4-d116-41f7-8af8-f62fb5bf036f", "text": "A paralelogramma szemközti oldalai párhuzamosak és egyenlő hosszúak.", "type": "true-false", "options": [{"id": "9768594f-c101-4b2b-937f-03dc2d5d946c", "text": "Igaz", "isCorrect": true}, {"id": "87ea5273-9f1b-4c0c-8de8-d7871388e7b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8f2a6419-a575-453e-8c70-f8e4789c351a", "text": "A négyzet egyben rombusz és téglalap is.", "type": "true-false", "options": [{"id": "b434336a-c826-46b3-8168-43900c3ac67e", "text": "Igaz", "isCorrect": true}, {"id": "82a346e0-93f2-45d8-893c-b56657c829cf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3af37767-3d85-4be4-ab66-2657425b4516", "text": "Hány átlója van egy négyszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ff605533-ab6e-4167-9e52-92473a83443a', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "2ede6a66-0598-4158-8c71-8b0767e35c58", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "0805306d-f000-44ff-99c9-811616355030", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "59c16691-74a6-4d85-9d64-2a0ffcc7cd75", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "1dc159fa-9b2f-4672-af05-756193a13d7a", "text": "Ha a területük 0", "isCorrect": false}, {"id": "2e3c8d05-1f78-4064-8189-3959cd541c42", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "5f9acf59-e875-4ace-a51a-3f7f2a09f6e7", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "0025385c-1c71-4f4b-8260-88aa42ce3393", "text": "Igaz", "isCorrect": true}, {"id": "250138ac-4fb2-452f-9fec-87c58dc48b89", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "87310839-0e24-4da7-8925-2a2d5be2e5bf", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "1154d9db-3da3-467b-952e-65ddd361e7a8", "text": "Igaz", "isCorrect": true}, {"id": "07662f5b-f092-4d07-bb11-a18303753d4f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7a721e32-296b-4a46-9e29-b8bba5239dff", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "78ff3264-fa7c-4735-a486-de16d5b5d0e1", "text": "Igaz", "isCorrect": false}, {"id": "5a206061-bee1-4cdf-a198-4858402c7399", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "9e93895b-87cf-4fc9-b720-b548a29385f1", "text": "Melyik állítás HAMIS az egybevágó alakzatokról?", "type": "multiple-choice", "options": [{"id": "ce4831e0-20cd-4262-a001-cb2061620ce2", "text": "A megfelelő oldalaik hossza eltérő", "isCorrect": true}, {"id": "d845ca9e-645f-4bd4-80b3-b45cb8a06b3f", "text": "A megfelelő szögeik egyenlőek", "isCorrect": false}, {"id": "31a7b8eb-0853-4840-a475-71103db85d20", "text": "A megfelelő oldalaik hossza egyenlő", "isCorrect": false}, {"id": "57a4995d-9425-4dfe-a004-16f2f305eee3", "text": "Területük megegyezik", "isCorrect": false}], "timeLimit": 15}, {"id": "969b59d7-0968-419d-90ec-9ef953e92e66", "text": "Minden négyzet egybevágó minden más négyzettel.", "type": "true-false", "options": [{"id": "0ab06cd3-6b36-460f-b8dc-4eca285d4d43", "text": "Igaz", "isCorrect": false}, {"id": "585c72cb-4232-4b1d-b7f7-5beef10a396e", "text": "Hamis (csak akkor ha oldalhosszuk megegyezik)", "isCorrect": true}], "timeLimit": 15}, {"id": "18fb2361-68df-4985-b1e5-8237517508e2", "text": "A tükrözés megtartja a szakaszok hosszát és a szögek nagyságát.", "type": "true-false", "options": [{"id": "30aa6f05-7360-4003-a895-28869c76e67c", "text": "Igaz", "isCorrect": true}, {"id": "db163251-5ba5-4f6c-86a4-2e12d63eef80", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;